#include "kernels.h"

// Part A baseline: one column at a time, loops in the order j, i.
void colsum_base(const int* A, int N, int* s) {
    for (int j = 0; j < N; j++)
        for (int i = 0; i < N; i++)
            s[j] += A[(size_t)i * N + j];
}

// Part B baseline: loops in the order i, k, j, with A[i][k] read once per k.
void abt_base(const int* A, const int* B, int N, int* C) {
    for (int i = 0; i < N; i++)
        for (int k = 0; k < N; k++) {
            int a = A[(size_t)i * N + k];
            for (int j = 0; j < N; j++)
                C[(size_t)i * N + j] += a * B[(size_t)j * N + k];
        }
}
